(14, 'obzor_news', '', 0, 0, 0, '<div class="obzor_news clearfix">\r\n	<div class="obzor_news_meta">\r\n		<span class="mini_date">[+date+]</span>\r\n		[+newsImage+]\r\n	</div>\r\n	<div class="obzor_news_content">\r\n		<h2><a href="[~[+id+]~]" title="[+pagetitle+]">[+pagetitle+]</a></h2><br>[+introtext+]\r\n	</div>\r\n</div>', 0),
(15, 'watches_filtering', '', 0, 0, 0, '<div class="watches_filtering">\r\n	<h4>Характеристики:</h4>\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Тип:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*watches_type*]\r\n		</div>\r\n	</div>\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Механизм:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*watches_mechanizm*]\r\n		</div>\r\n	</div>\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Батарея:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*watches_battery*]\r\n		</div>\r\n	</div>\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Корпус:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*watches_box*]\r\n		</div>\r\n	</div>\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Безель:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*bezel*]\r\n		</div>\r\n	</div>\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Циферблат:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*watches_table*]\r\n		</div>\r\n	</div>\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Будильник:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*watches_alarm*]\r\n		</div>\r\n	</div>\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Стрелки:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*watches_str*]\r\n		</div>\r\n	</div>\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Хронограф:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*watches_chrono*]\r\n		</div>\r\n	</div>\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Стекло:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*watches_steklo*]\r\n		</div>\r\n	</div>\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Дата:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*watches_date*]\r\n		</div>\r\n	</div>\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			День недели:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*watches_days*]\r\n		</div>\r\n	</div>\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Заводная головка:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*watches_heads*]\r\n		</div>\r\n	</div>\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Размеры:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*watches_razmer*]\r\n		</div>\r\n	</div>\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Вес:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*watches_ves*]\r\n		</div>\r\n	</div>\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Подсветка:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*watches_trigalights*]\r\n		</div>\r\n	</div>\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Водозащищенность:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*watches_resistant*]\r\n		</div>\r\n	</div>\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Браслет:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*watches_braslet*]\r\n		</div>\r\n	</div>\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Индивидуальный номер:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*watches_no*]\r\n		</div>\r\n	</div>\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Упаковка:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*watches_package*]\r\n		</div>\r\n	</div>\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Гарантия:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*watches_guarantee*]\r\n		</div>\r\n	</div>\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Производитель:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*watches_manufactured*]\r\n		</div>\r\n	</div>\r\n	[+phx:if=`[*instruction*]`:is=``:then=``:else=`\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			&nbsp;\r\n		</div>\r\n		<div class="filtering_content">\r\n			<a href="[*instruction*]" target="_blank" title="Скачать инструкцию" class=""><i class="icon-white icon-download"></i> Скачать инструкцию <small>(.pdf)</small></a>\r\n		</div>\r\n	</div>\r\n	`+]\r\n</div>', 0),
(16, 'mini-gallery', '', 0, 0, 0, '[+phx:if=`[*watches-image-1*] `:is=``:then=``:else=`\n<div class="box_preview_inner">\n	<div class="preview_img">\n		<a href="[*watches-image-1*]" rel="shadowbox[group]"><img src="[*watches-image-1:replace=`medium,mini`*]" /></a>\n	</div>\n</div>\n`+]\n[+phx:if=`[*watches-image-2*] `:is=``:then=``:else=`\n<div class="box_preview_inner">\n	<div class="preview_img">\n		<a href="[*watches-image-2*]" rel="shadowbox[group]"><img src="[*watches-image-2:replace=`medium,mini`*]" /></a>\n	</div>\n</div>\n`+]\n[+phx:if=`[*watches-image-3*] `:is=``:then=``:else=`\n<div class="box_preview_inner">\n	<div class="preview_img">\n		<a href="[*watches-image-3*]" rel="shadowbox[group]"><img src="[*watches-image-3:replace=`medium,mini`*]" /></a>\n	</div>\n</div>\n`+]\n[+phx:if=`[*watches-image-4*] `:is=``:then=``:else=`\n<div class="box_preview_inner">\n	<div class="preview_img">\n		<a href="[*watches-image-4*]" rel="shadowbox[group]"><img src="[*watches-image-4:replace=`medium,mini`*]" /></a>\n	</div>\n</div>\n`+]', 0),
(17, 'archive', '', 0, 0, 0, '<div class="clearfix">\n	<h3><a href="[~[+id+]~]" title="Архив за [+pagetitle+] год">Архив за [+pagetitle+] год</a></h3>\n</div>', 0),
(18, 'braslets', '', 0, 0, 0, '<div class="prebras">\n	<div class="prebras_image">\n		<a href="[~[+id+]~]" title="[+pagetitle+]"><img src="/assets/images/braslets/mini/[+id+].jpg" alt="[+pagetitle+]" ></a>\n	</div>\n	<div class="prebras_title cuprum">\n		<a href="[~[+id+]~]" title="[+pagetitle+]">[+pagetitle+]</a>\n	</div>\n</div>', 0),
(19, 'form-tpl', '', 0, 0, 0, '<div id="contact_form">\r\n            \r\n                  <h3>Обратная связь</h3>         \r\n                       [+validationmessage+]       \r\n                  <form method="post" action="[~[*id*]~]">\r\n                    \r\n                        <input type="hidden" name="formid" value="Send" />\r\n                        <label for="author">Ваше имя</label> <input type="text" id="author" name="author" class="required input_field" eform="Имя::1" />\r\n                        <div class="cleaner_h10"></div>\r\n                        \r\n                        <label for="email">Email:</label> <input type="text" id="email" name="email" class="validate-email required input_field" eform="Адрес электронной почты:email:1" />\r\n                        <div class="cleaner_h10"></div>\r\n                        \r\n                        <label for="otdel">Тема сообщения</label> \r\n                        <select name="otdel" class="input_field">\r\n\r\n<option value="Вопрос-ответ: Гарантия">Гарантия</option>\r\n<option value="Вопрос-ответ: Эксплуатация">Эксплуатация</option>\r\n<option value="Вопрос-ответ: Ремонт">Ремонт</option>\r\n<option value="Вопрос-ответ: Ремонт">Дилерство</option>\r\n<option value="Вопрос-ответ: Другое">Другое</option>\r\n\r\n                        </select>\r\n                        <div class="cleaner_h10"></div>\r\n                        \r\n                        <label for="text">Текст сообщения</label> <textarea id="text" name="text" rows="0" cols="0" class="required" eform="Текст сообщения:html:1"></textarea>\r\n                        <div class="cleaner_h10"></div>\r\n                        \r\n					  <p>Введите этот код:<br/> \r\n                            <img src="[+verimageurl+]" alt="Код проверки" border="0"/></p>\r\n                            <input type="text" class="vericodeform input_field" name="vericode" /><br /><br />\r\n                    \r\n                        \r\n                        <input type="submit" class="submit_btn" name="submit" id="submit" value=" Отправить " />\r\n                        <input type="reset" class="submit_btn" name="reset" id="reset" value=" Сбросить " />\r\n                    \r\n                  </form>\r\n\r\n            </div>', 0),
(20, 'thank-tpl', '', 0, 0, 0, '<strong>Спасибо, что воспользовались формой обратной связи на нашем сайте.</strong>\n<p>Ваше сообщение будет рассмотрено в кротчайшие сроки, и, если оно требует ответа, Вы обязательно его получите.</p>', 0),
(21, 'report-tpl', '', 0, 0, 0, '<p>Это сообщение было отправлено посетителем по имени [+author+] с помощью формы обратной связи. </p>\n<table>\n<tr valign="top"><td><b>Имя:</b></td><td>[+author+]</td></tr>\n<tr valign="top"><td><b>Email:</b>:</td><td>[+email+]</td></tr>\n<tr valign="top"><td><b>Сообщение:</b></td><td>[+text+]</td></tr>\n</table>\n<p>Вы можете использовать эту ссылку для ответа: <a href="mailto:[+email+]?subject=RE:[+subject+]">[+email+]</a></p>', 0),
(22, 'form', '', 0, 0, 0, '[!eForm? &formid=`Send` &tpl=`form-tpl` &to=`info@traser.ru` &mailselector=`otdel` &report=`report-tpl` &thankyou=`thank-tpl` &vericode=`1` &subject=`Сообщение с сайта TRASER`!]', 0),
(23, 'feedback', 'форма обратной связи', 0, 7, 0, '[!eForm? &formid=`feedbackForm` &subject=`Сообщение с сайта` &tpl=`eFeedbackForm` &report=`eFeedbackReport` &gotoid=`[*id*]` &vericode=`1` !] \r\n\r\n', 0),
(24, 'mm_rules-1_1b-d7_1_1', 'Default ManagerManager rules.', 0, 2, 0, '// more example rules are in assets/plugins/managermanager/example_mm_rules.inc.php\r\n\r\nmm_widget_showimagetvs(); // Показываем превью ТВ\r\n\r\nmm_renameField(\'log\', \'Дочерние ресурсы отображаются в дереве\');\r\nmm_changeFieldHelp(\'log\', \'Это поле используется для папок с большим числом вложенных страниц\');\r\n\r\nmm_createTab(\'Для SEO\', \'seo\', \'\', \'\', \'\', \'\');\r\nmm_moveFieldsToTab(\'titl,keyw,desc,seoOverride,noIndex,sitemap_changefreq,sitemap_priority,sitemap_exclude\', \'seo\', \'\', \'\');\r\nmm_widget_tags(\'keyw\',\',\'); // Give blog tag editing capabilities to the \'documentTags (3)\' TV\r\n\r\n\r\n//mm_createTab(\'Изображения\', \'photos\', \'\', \'\', \'\', \'850\');\r\n//mm_moveFieldsToTab(\'images,photos\', \'photos\', \'\', \'\');\r\n\r\n//mm_hideFields(\'longtitle,description,link_attributes,menutitle,content\', \'\', \'6,7\');\r\n\r\n//mm_hideTemplates(\'0,5,8,9,11,12\', \'2,3\');\r\n\r\n//mm_hideTabs(\'settings, access\', \'2\');\r\n\r\n//mm_widget_evogallery(1, Галерея, \'1,2,3\', 3);   // подключаем галерею \r\n//mm_galleryLink($fields, $roles, $templates, $moduleid);\r\n//mm_widget_evogallery($moduleid, $title, $roles, $templates);\r\n', 0),
(25, 'header-1_1b-d7_1_1', 'шапка', 0, 15, 0, '<meta http-equiv="Content-Type" content="text/html; charset=[(modx_charset)]" /> \r\n<title>[*titl*]</title>\r\n[*noIndex*]\r\n<meta name="keywords" content="[*keyw*]" />\r\n<meta name="description" content="[*desc*]" />\r\n<base href="[(site_url)]"/>\r\n', 0),
(26, 'eFeedbackReport', 'eFeedbackReport  шаблон отправки на почту', 0, 7, 0, '<p>Прислано человеком, с именем: [+name+] . Подробности ниже:</p>\r\n<table>\r\n<tr valign="top"><td>Имя:</td><td>[+name+]</td></tr>\r\n<tr valign="top"><td>E-mail:</td><td>[+email+]</td></tr>\r\n<tr valign="top"><td>Номер телефона:</td><td>[+phone+]</td></tr>\r\n<tr valign="top"><td>Текст сообщения:</td><td>[+comments+]</td></tr>\r\n</table>\r\n<p>Можно использовать ссылку для ответа: <a href="mailto:[+email+]?subject=RE:[+subject+]">[+email+]</a></p>\r\n\r\n', 0),
(27, 'footer-1_1b-d7_1_1', 'низ сайта', 0, 15, 0, '<!--  Mem : [^m^], MySQL: [^qt^], [^q^] request(s), PHP: [^p^], total: [^t^], document from [^s^]. -->', 0),
(28, 'eFeedbackForm', 'eFeedbackForm Шаблон формы обратной связи', 0, 7, 0, '<p><span style="color:#900;">[+validationmessage+]</span></p>\r\n\r\n<form  class="eform" method="post" action="[~[*id*]~]">\r\n\r\n<input type="hidden" name="formid" value="feedbackForm" />\r\n<input value="" name="special" class="special" type="text" eform="Спец:date:0"  style="display:none;" />\r\n<p>\r\n    <input type="text" name="name" id="name" class="grid_3" value=""  eform="Имя:string:1"/>\r\n    <label for="name">Ваше имя</label>\r\n</p>\r\n            \r\n<p>\r\n    <input type="text" name="email" id="email" class="grid_3" value="" eform="E-mail:email:1" />\r\n    <label for="email">Ваш E-mail</label>\r\n</p>\r\n            \r\n<p>\r\n    <input type="text" name="phone" id="subject" class="grid_3" value="" eform="Номер телефона:string:1"/>\r\n    <label for="subject">Номер телефона</label>\r\n</p>\r\n            \r\n<p>\r\n    <textarea name="comments" id="message" class="grid_6" cols="50" rows="10" eform="Текст сообщения:string:1"></textarea>\r\n</p>\r\n<p>Введите код с картинки: <br />\r\n    <input type="text" class="ver" name="vericode" /><img class="feed" src="[+verimageurl+]" alt="Введите код" />\r\n</p>            \r\n<p>\r\n    <input type="submit" name="submit" class="subeform grid_2" value="Отправить сообщение"/>\r\n </p>\r\n\r\n</form>\r\n\r\n\r\n \r\n\r\n', 0),
(29, 'braslets_new_filtering', '', 0, 0, 0, '<div class="watches_filtering">\r\n	<h4>Характеристики:</h4>\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Материал:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*watches_type*]\r\n		</div>\r\n	</div>\r\n		<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Размер:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*watches_razmer*]\r\n		</div>\r\n	</div>\r\n		<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Производитель:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*watches_manufactured*]\r\n		</div>\r\n	</div>\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Рекомендованная цена:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*price*]\r\n		</div>\r\n	</div>\r\n	[+phx:if=`[*instruction*]`:is=``:then=``:else=`\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			&nbsp;\r\n		</div>		\r\n	</div>\r\n	`+]\r\n</div>', 0),
(30, 'braslets_filtering', '', 0, 0, 0, '<div class="watches_filtering">\r\n	<h4>Характеристики ремешка/браслета:</h4>\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Материал:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*watches_type*]\r\n		</div>\r\n	</div>\r\n		<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Размеры:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*watches_razmer*]\r\n		</div>\r\n	</div>\r\n		<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Производитель:\r\n		</div>\r\n		<div class="filtering_content">\r\n			[*watches_manufactured*]\r\n		</div>\r\n	</div>\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			Рекомендованная цена:\r\n		</div>\r\n		<div class="filtering_content">\r\n			<a href="/index.php?id=6" title="Где купить"> [*price*] руб.</a>\r\n		</div>\r\n	</div>\r\n	[+phx:if=`[*instruction*]`:is=``:then=``:else=`\r\n	<div class="filtering_row clearfix">\r\n		<div class="filtering_title">\r\n			&nbsp;\r\n		</div>\r\n		<div class="filtering_content">\r\n			<a href="[*instruction*]" title="Скачать инструкцию" class=""><i class="icon-white icon-download"></i> Скачать инструкцию <small>(.pdf)</small></a>\r\n		</div>\r\n	</div>\r\n	`+]\r\n</div>', 0);
INSERT INTO `modx_site_modules` (`id`, `name`, `description`, `editor_type`, `disabled`, `category`, `wrap`, `locked`, `icon`, `enable_resource`, `resourcefile`, `createdon`, `editedon`, `guid`, `enable_sharedparams`, `properties`, `modulecode`) VALUES
(1, 'Doc Manager', '<strong>1.1</strong> Quickly perform bulk updates to the Documents in your site including templates, publishing details, and permissions', 0, 0, 3, 0, 0, '', 0, '', 0, 0, 'docman435243542tf542t5t', 1, '', 'include_once(MODX_BASE_PATH.\'assets/modules/docmanager/classes/docmanager.class.php\');\ninclude_once(MODX_BASE_PATH.\'assets/modules/docmanager/classes/dm_frontend.class.php\');\ninclude_once(MODX_BASE_PATH.\'assets/modules/docmanager/classes/dm_backend.class.php\');\n\n$dm = new DocManager($modx);\n$dmf = new DocManagerFrontend($dm, $modx);\n$dmb = new DocManagerBackend($dm, $modx);\n\n$dm->ph = $dm->getLang();\n$dm->ph[\'theme\'] = $dm->getTheme();\n$dm->ph[\'ajax.endpoint\'] = MODX_SITE_URL.\'assets/modules/docmanager/tv.ajax.php\';\n$dm->ph[\'datepicker.offset\'] = $modx->config[\'datepicker_offset\'];\n$dm->ph[\'datetime.format\'] = $modx->config[\'datetime_format\'];\n\nif (isset($_POST[\'tabAction\'])) {\n    $dmb->handlePostback();\n} else {\n    $dmf->getViews();\n    echo $dm->parseTemplate(\'main.tpl\', $dm->ph);\n}'),
(2, 'Easy Newsletter', '<strong>0.3</strong> Newsletter manager.', 0, 0, 0, 0, 0, '', 0, '', 0, 0, '4019ba3dbe5f822ed0c0770b81b65d2d', 0, '&modId=Module ID;int;2 &path=Path;text;../assets/modules/easynewsletter/', '/*\nEasy Newsletter 0.3\nCopyright by: Flux - www.simpleshop.dk\nDate: 10. september 2007\nNotes: This newsletter system is heavily inspired by KoopsmailinglistX so a bow in respect and appreciation to the original author Jasper Koops and sottwell@sottwell.com who ported it to MODx.\n\nThis is version 0.3 so there might be some errors I have missed and functionality that you might think is missing. I have not tested the system with say 1000 subscribers. Error logging/handling is very simple - It will just stop if an error has occurred with no resume function.\n---------------------------------------------------------------------\nThis file is part of Easy Newsletter 0.3\n\nEasy Newsletter 0.3 is free software; you can redistribute it and/or modify\nit under the terms of the GNU General Public License as published by\nthe Free Software Foundation; either version 3 of the License, or\n(at your option) any later version.\n\nEasy Newsletter 0.3 is distributed in the hope that it will be useful,\nbut WITHOUT ANY WARRANTY; without even the implied warranty of\nMERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\nGNU General Public License for more details.\n\nYou should have received a copy of the GNU General Public License\nalong with this program.  If not, see <http://www.gnu.org/licenses/>. \n---------------------------------------------------------------------*/\n\n$sql = "SHOW TABLES LIKE \'easynewsletter_config\'";\n$rs = $modx->db->query($sql);\n$count = $modx->db->getRecordCount($rs);\nif($count < 1) {\n  $sql = "CREATE TABLE IF NOT EXISTS `easynewsletter_config` (\n  `id` int(11) NOT NULL default \'0\',\n  `mailmethod` varchar(20) NOT NULL default \'\',\n  `port` int(11) NOT NULL default \'0\',\n  `smtp` varchar(200) NOT NULL default \'\',\n  `auth` varchar(5) NOT NULL default \'\',\n  `authuser` varchar(100) NOT NULL default \'\',\n  `authpassword` varchar(100) NOT NULL default \'\',\n  `sendername` varchar(200) NOT NULL default \'\',\n  `senderemail` varchar(200) NOT NULL default \'\',\n  `lang_frontend` varchar(100) NOT NULL default \'\',\n  `lang_backend` varchar(100) NOT NULL default \'\',\n  PRIMARY KEY  (`id`)\n)";\n$modx->db->query($sql);\n$sql = "INSERT INTO `easynewsletter_config` VALUES (1, \'IsSMTP\', 0, \'\', \'false\', \'\', \'\', \'\', \'\', \'english\', \'english\')";\n$modx->db->query($sql);\n  $sql = "CREATE TABLE IF NOT EXISTS `easynewsletter_newsletter` (\n  `id` int(11) NOT NULL auto_increment,\n  `date` date NOT NULL default \'0000-00-00\',\n  `status` int(11) NOT NULL default \'0\',\n  `sent` int(11) NOT NULL default \'0\',\n  `header` longtext,\n  `subject` text NOT NULL,\n  `newsletter` longtext,\n  `footer` longtext,\n  PRIMARY KEY  (`id`)\n)";\n$modx->db->query($sql);\n$sql = "CREATE TABLE IF NOT EXISTS `easynewsletter_subscribers` (\n  `id` int(11) NOT NULL auto_increment,\n  `firstname` varchar(50) NOT NULL default \'\',\n  `lastname` varchar(50) NOT NULL default \'\',\n  `email` varchar(50) NOT NULL default \'\',\n  `status` int(11) NOT NULL default \'1\',\n  `blocked` int(11) NOT NULL default \'0\',\n  `lastnewsletter` varchar(50) NOT NULL default \'\',\n  `created` date NOT NULL default \'0000-00-00\',\n  PRIMARY KEY  (`id`)\n)";\n$modx->db->query($sql);\necho \'Easy Newsletter has now been installed. Please click <strong>Easy Newsletter</strong> in the navigation bar.\';\n} else {\n$theme = $modx->config[\'manager_theme\'];\n$sql = "SELECT * FROM `easynewsletter_config` WHERE `id` = 1";\n$result = $modx->db->query($sql);\ninclude($path.\'languages/\'.mysql_result($result,$i,"lang_backend").\'.php\');\necho \'\n<html>\n<head>\n	<title>MODx</title>\n	<meta http-equiv="Content-Type" content="text/html; charset=UTF-8" />\n	<link rel="stylesheet" type="text/css" href="media/style/\'.$theme.\'/style.css?" />\n</head>\n<body>\n<br />\n<div class="sectionHeader">Easy Newsletter 0.3 - &copy; 2007 <a href="http://www.simpleshop.dk" target="_blank">SimpleShop.dk</a></div><div class="sectionBody">\n<div class="searchbar">\n&nbsp;&nbsp;&nbsp;<b>\'.$lang_links_header.\'</b>&nbsp;&nbsp;&nbsp;<a href="index.php?a=112&id=\'.$modId.\'&action=1">\'.$lang_links_subscribers.\'</a> | <a href="index.php?a=112&id=\'.$modId.\'&p=1&action=1">\'.$lang_links_newsletter.\'</a> | <a href="index.php?a=112&id=\'.$modId.\'&p=2&action=1">\'.$lang_links_configuration.\'</a>\n</div><br />\';\ninclude($path.\'backend.php\');\necho \'\n</div>\n</body>\n</html>\n\';\nreturn;\n}\n'),
(3, 'JoCo', '', 0, 0, 0, 0, 0, '', 0, '', 0, 0, '79835051e7b0cd27eecc2a4051a1abf3', 0, '', '/*********************************\r\nModule : JoCo (Jot Comments module)\r\nVersion : 0.9.2\r\nAuthor : AHHP ~ Boplo.ir\r\nOn : 2009/03/29\r\n*********************************/\r\ninclude_once($modx->config[\'base_path\'].\'assets/modules/JoCo/joco.php\');\r\n\r\n'),
(4, 'Extras', '<strong>0.1.2</strong> first repository for MODX EVO', 0, 0, 3, 0, 0, '', 0, '', 0, 0, 'store435243542tf542t5t', 1, '', '//AUTHORS: Bumkaka & Dmi3yy \r\ninclude_once(\'../assets/modules/store/core.php\');');
INSERT INTO `modx_site_plugins` (`id`, `name`, `description`, `editor_type`, `category`, `cache_type`, `plugincode`, `locked`, `properties`, `disabled`, `moduleguid`) VALUES
(1, 'CodeMirror', '<strong>1.2b</strong> JavaScript library that can be used to create a relatively pleasant editor interface based on CodeMirrir 3.13', 0, 3, 0, '$_CM_BASE = \'assets/plugins/codemirror/\';\n\n$_CM_URL = $modx->config[\'site_url\'] . $_CM_BASE;\n\nrequire(MODX_BASE_PATH. $_CM_BASE .\'codemirror.plugin.php\');\n\n', 0, '&theme=Theme;list;default,ambiance,blackboard,cobalt,eclipse,elegant,erlang-dark,lesser-dark,midnight,monokai,neat,night,rubyblue,solarized,twilight,vibrant-ink,xq-dark,xq-light; &indentUnit=Indent unit;int;4 &tabSize=The width of a tab character;int;4 &lineWrapping=lineWrapping;list;true,false;true &matchBrackets=matchBrackets;list;true,false;false &activeLine=activeLine;list;true,false;false &emmet=emmet;list;true,false;true &search=search;list;true,false;true', 1, ''),
(2, 'FileSource', '<strong>0.1</strong> Save snippet and plugins to file', 0, 3, 0, 'require MODX_BASE_PATH.\'assets/plugins/filesource/plugin.filesource.php\';', 0, '', 0, ''),
(3, 'Forgot Manager Login', '<strong>1.1.6</strong> Resets your manager login when you forget your password via email confirmation', 0, 3, 0, 'require MODX_BASE_PATH.\'assets/plugins/forgotmanagerlogin/plugin.forgotmanagerlogin.php\';', 0, '', 1, ' '),
(4, 'ManagerManager', '<strong>0.3.11</strong> Customize the MODx Manager to offer bespoke admin functions for end users.', 0, 3, 0, '$js_default_url_local = $modx->config[\'site_url\']. \'/assets/js/jquery.min.js\';\n$js_default_url_remote = \'http://ajax.googleapis.com/ajax/libs/jquery/1.8/jquery.min.js\';\n$asset_path = $modx->config[\'base_path\'] . \'assets/plugins/managermanager/mm.inc.php\';\ninclude($asset_path);\n', 0, '&config_chunk=Configuration Chunk;text;mm_rules; &remove_deprecated_tv_types_pref=Remove deprecated TV types;list;yes,no;yes &which_jquery=jQuery source;list;local (assets/js),remote (google code),manual url (specify below);local (assets/js) &js_src_type=jQuery URL override;text;', 1, ''),
(5, 'Quick Manager+', '<strong>1.5.6</strong> Enables QuickManager+ front end content editing support', 0, 3, 0, '// In manager\nif (isset($_SESSION[\'mgrValidated\'])) {\n\n    $show = TRUE;\n\n    if ($disabled  != \'\') {\n        $arr = array_filter(array_map(\'intval\', explode(\',\', $disabled)));\n        if (in_array($modx->documentIdentifier, $arr)) {\n            $show = FALSE;\n        }\n    }\n\n    if ($show) {\n        // Replace [*#tv*] with QM+ edit TV button placeholders\n        if ($tvbuttons == \'true\') {\n            $e = $modx->Event;\n            if ($e->name == \'OnParseDocument\') {\n                 $output = &$modx->documentOutput;\n                 $output = preg_replace(\'~\\[\\*#(.*?)\\*\\]~\', \'<!-- \'.$tvbclass.\' $1 -->[*$1*]\', $output);\n                 $modx->documentOutput = $output;\n             }\n         }\n        // In manager\n        if (isset($_SESSION[\'mgrValidated\'])) {\n            include_once($modx->config[\'base_path\'].\'assets/plugins/qm/qm.inc.php\');\n            $qm = new Qm($modx, $jqpath, $loadmanagerjq, $loadfrontendjq, $noconflictjq, $loadtb, $tbwidth, $tbheight, $hidefields, $hidetabs, $hidesections, $addbutton, $tpltype, $tplid, $custombutton, $managerbutton, $logout, $autohide, $editbuttons, $editbclass, $newbuttons, $newbclass, $tvbuttons, $tvbclass);\n        }\n    }\n}', 0, '&jqpath=Path to jQuery;text;assets/js/jquery.min.js &loadmanagerjq=Load jQuery in manager;list;true,false;false &loadfrontendjq=Load jQuery in front-end;list;true,false;true &noconflictjq=jQuery noConflict mode in front-end;list;true,false;true &loadtb=Load modal box in front-end;list;true,false;true &tbwidth=Modal box window width;text;80% &tbheight=Modal box window height;text;90% &hidefields=Hide document fields from front-end editors;text;parent &hidetabs=Hide document tabs from front-end editors;text; &hidesections=Hide document sections from front-end editors;text; &addbutton=Show add document here button;list;true,false;true &tpltype=New document template type;list;parent,id,selected;parent &tplid=New document template id;int;3 &custombutton=Custom buttons;textarea; &managerbutton=Show go to manager button;list;true,false;true &logout=Logout to;list;manager,front-end;manager &disabled=Plugin disabled on documents;text; &autohide=Autohide toolbar;list;true,false;true &editbuttons=Inline edit buttons;list;true,false;false &editbclass=Edit button CSS class;text;qm-edit &newbuttons=Inline new resource buttons;list;true,false;false &newbclass=New resource button CSS class;text;qm-new &tvbuttons=Inline template variable buttons;list;true,false;false &tvbclass=Template variable button CSS class;text;qm-tv &1=undefined;; ', 1, ''),
(6, 'Search Highlight', '<strong>1.5</strong> Used with AjaxSearch to show search terms highlighted on page linked from search results', 0, 4, 0, '/*\n  ------------------------------------------------------------------------\n  Plugin: Search_Highlight v1.5\n  ------------------------------------------------------------------------\n  Changes:\n  18/03/10 - Remove possibility of XSS attempts being passed in the URL\n           - look-behind assertion improved\n  29/03/09 - Removed urldecode calls;\n           - Added check for magic quotes - if set, remove slashes\n           - Highlights terms searched for when target is a HTML entity\n  18/07/08 - advSearch parameter and pcre modifier added\n  10/02/08 - Strip_tags added to avoid sql injection and XSS. Use of $_REQUEST\n  01/03/07 - Added fies/updates from forum from users mikkelwe/identity\n  (better highlight replacement, additional div around term/removal message)\n  ------------------------------------------------------------------------\n  Description: When a user clicks on the link from the AjaxSearch results\n    the target page will have the terms highlighted.\n  ------------------------------------------------------------------------\n  Created By:  Susan Ottwell (sottwell@sottwell.com)\n               Kyle Jaebker (kjaebker@muddydogpaws.com)\n\n  Refactored by Coroico (www.evo.wangba.fr) and TS\n  ------------------------------------------------------------------------\n  Based off the the code by Susan Ottwell (www.sottwell.com)\n    http://modxcms.com/forums/index.php/topic,1237.0.html\n  ------------------------------------------------------------------------\n  CSS:\n    The classes used for the highlighting are the same as the AjaxSearch\n  ------------------------------------------------------------------------\n  Notes:\n    To add a link to remove the highlighting and to show the searchterms\n    put the following on your page where you would like this to appear:\n\n      <!--search_terms-->\n\n    Example output for this:\n\n      Search Terms: the, template\n      Remove Highlighting\n\n    Set the following variables to change the text:\n\n      $termText - the text before the search terms\n      $removeText - the text for the remove link\n  ------------------------------------------------------------------------\n*/\nglobal $database_connection_charset;\n// Conversion code name between html page character encoding and Mysql character encoding\n// Some others conversions should be added if needed. Otherwise Page charset = Database charset\n$pageCharset = array(\n  \'utf8\' => \'UTF-8\',\n  \'latin1\' => \'ISO-8859-1\',\n  \'latin2\' => \'ISO-8859-2\'\n);\n\nif (isset($_REQUEST[\'searched\']) && isset($_REQUEST[\'highlight\'])) {\n\n  // Set these to customize the text for the highlighting key\n  // --------------------------------------------------------\n     $termText = \'<div class="searchTerms">Search Terms: \';\n     $removeText = \'Remove Highlighting\';\n  // --------------------------------------------------------\n\n  $highlightText = $termText;\n  $advsearch = \'oneword\';\n\n  $dbCharset = $database_connection_charset;\n  $pgCharset = array_key_exists($dbCharset,$pageCharset) ? $pageCharset[$dbCharset] : $dbCharset;\n\n  // magic quotes check\n  if (get_magic_quotes_gpc()){\n    $searched = strip_tags(stripslashes($_REQUEST[\'searched\']));\n    $highlight = strip_tags(stripslashes($_REQUEST[\'highlight\']));\n    if (isset($_REQUEST[\'advsearch\'])) $advsearch = strip_tags(stripslashes($_REQUEST[\'advsearch\']));\n  }\n  else {\n    $searched = strip_tags($_REQUEST[\'searched\']);\n    $highlight = strip_tags($_REQUEST[\'highlight\']);\n    if (isset($_REQUEST[\'advsearch\'])) $advsearch = strip_tags($_REQUEST[\'advsearch\']);\n  }\n\n  if ($advsearch != \'nowords\') {\n\n    $searchArray = array();\n    if ($advsearch == \'exactphrase\') $searchArray[0] = $searched;\n    else $searchArray = explode(\' \', $searched);\n\n    $searchArray = array_unique($searchArray);\n    $nbterms = count($searchArray);\n    $searchTerms = array();\n    for($i=0;$i<$nbterms;$i++){\n      // Consider all possible combinations\n      $word_ents = array();\n      $word_ents[] = $searchArray[$i];\n      $word_ents[] = htmlentities($searchArray[$i], ENT_NOQUOTES, $pgCharset);\n      $word_ents[] = htmlentities($searchArray[$i], ENT_COMPAT, $pgCharset);\n      $word_ents[] = htmlentities($searchArray[$i], ENT_QUOTES, $pgCharset);\n      // Avoid duplication\n      $word_ents = array_unique($word_ents);\n      foreach($word_ents as $word) $searchTerms[]= array(\'term\' => $word, \'class\' => $i+1);\n    }\n\n    $output = $modx->documentOutput; // get the parsed document\n    $body = explode("<body", $output); // break out the head\n\n    $highlightClass = explode(\' \',$highlight); // break out the highlight classes\n    /* remove possibility of XSS attempts being passed in URL */\n    foreach ($highlightClass as $key => $value) {\n       $highlightClass[$key] = preg_match(\'/[^A-Za-z0-9_-]/ms\', $value) == 1 ? \'\' : $value;\n    }\n\n    $pcreModifier = ($pgCharset == \'UTF-8\') ? \'iu\' : \'i\';\n    $lookBehind = \'/(?<!&|&[\\w#]|&[\\w#]\\w|&[\\w#]\\w\\w|&[\\w#]\\w\\w\\w|&[\\w#]\\w\\w\\w\\w|&[\\w#]\\w\\w\\w\\w\\w)\';  // avoid a match with a html entity\n    $lookAhead = \'(?=[^>]*<)/\'; // avoid a match with a html tag\n\n    $nbterms = count($searchTerms);\n    for($i=0;$i<$nbterms;$i++){\n      $word = $searchTerms[$i][\'term\'];\n      $class = $highlightClass[0].\' \'.$highlightClass[$searchTerms[$i][\'class\']];\n\n      $highlightText .= ($i > 0) ? \', \' : \'\';\n      $highlightText .= \'<span class="\'.$class.\'">\'.$word.\'</span>\';\n\n      $pattern = $lookBehind . preg_quote($word, \'/\') . $lookAhead . $pcreModifier;\n      $replacement = \'<span class="\' . $class . \'">${0}</span>\';\n      $body[1] = preg_replace($pattern, $replacement, $body[1]);\n    }\n\n    $output = implode("<body", $body);\n\n    $removeUrl = $modx->makeUrl($modx->documentIdentifier);\n    $highlightText .= \'<br /><a href="\'.$removeUrl.\'" class="ajaxSearch_removeHighlight">\'.$removeText.\'</a></div>\';\n\n    $output = str_replace(\'<!--search_terms-->\',$highlightText,$output);\n    $modx->documentOutput = $output;\n  }\n}', 0, '', 1, ''),
(7, 'TinyMCE Rich Text Editor', '<strong>3.5.8</strong> Javascript WYSIWYG Editor', 0, 3, 0, 'require MODX_BASE_PATH.\'assets/plugins/tinymce/plugin.tinymce.php\';\n', 0, '&customparams=Custom Parameters;textarea;valid_elements : "*[*]", &mce_formats=Block Formats;text;p,h1,h2,h3,h4,h5,h6,div,blockquote,code,pre &entity_encoding=Entity Encoding;list;named,numeric,raw;named &entities=Entities;text; &mce_path_options=Path Options;list;Site config,Absolute path,Root relative,URL,No convert;Site config &mce_resizing=Advanced Resizing;list;true,false;true &disabledButtons=Disabled Buttons;text; &link_list=Link List;list;enabled,disabled;enabled &webtheme=Web Theme;list;simple,editor,creative,custom;simple &webPlugins=Web Plugins;text;style,advimage,advlink,searchreplace,contextmenu,paste,fullscreen,xhtmlxtras,media &webButtons1=Web Buttons 1;text;undo,redo,selectall,|,pastetext,pasteword,|,search,replace,|,hr,charmap,|,image,link,unlink,anchor,media,|,cleanup,removeformat,|,fullscreen,code,help &webButtons2=Web Buttons 2;text;bold,italic,underline,strikethrough,sub,sup,|,|,blockquote,bullist,numlist,outdent,indent,|,justifyleft,justifycenter,justifyright,justifyfull,|,styleselect,formatselect,|,styleprops &webButtons3=Web Buttons 3;text; &webButtons4=Web Buttons 4;text; &webAlign=Web Toolbar Alignment;list;ltr,rtl;ltr &width=Width;text;95% &height=Height;text;500', 1, ''),
(8, 'TransAlias', '<strong>1.0.2</strong> Human readible URL translation supporting multiple languages and overrides', 0, 3, 0, 'require MODX_BASE_PATH.\'assets/plugins/transalias/plugin.transalias.php\';', 0, '&table_name=Trans table;list;common,russian,dutch,german,czech,utf8,utf8lowercase;utf8lowercase &char_restrict=Restrict alias to;list;lowercase alphanumeric,alphanumeric,legal characters;legal characters &remove_periods=Remove Periods;list;Yes,No;No &word_separator=Word Separator;list;dash,underscore,none;dash &override_tv=Override TV name;string;', 1, ''),
(9, 'TVimageResizer', 'Плагин для создания миниатюр изображений', 0, 0, 0, 'require MODX_BASE_PATH.\'assets/plugins/tvimageresizer/TVimageResizer.inc.php\';', 0, '&tv_ids=TV IDs;string;3, 33, 34, 35, 36 &dirs=Thumb folders;string;medium~mini &width=Width;string;300~155 &height=Height;string;520~270 &rcorner=Corners percentage of clipping;string; &backgroundColor=Background color;string; &watermark=Watermark image path (png);string; &watermarkPos=Watermark position;string;90% 90% &cprighttext=Copyright text;string; &quality=Quality;int;100 &mirror=Mirror effect;list;yes,no;no &crop=Cropping;list;yes,no,crop_resized,fill_resized;crop_resized &save_o_name=Save only name;list;yes,no;no &rename_images=Rename images;list;yes,no;no &refresh_all_images=Refresh all images;list;yes,no;no', 0, ' '),
(10, 'PHx', '', 0, 0, 0, '//<?php\n/**\n * phx \n * \n * (Placeholders Xtended) Adds the capability of output modifiers when using placeholders, template variables and settings tags\n *\n * @category    plugin\n * @version     2.2.0\n * @author      Armand "bS" Pondman (apondman@zerobarrier.nl)\n * @internal    @properties &phxdebug=Log events;int;0 &phxmaxpass=Max. Passes;int;50\n * @internal    @events OnParseDocument\n * @internal    @modx_category Manager and Admin\n */\n\ninclude_once $modx->config[\'rb_base_dir\'] . "plugins/phx/phx.parser.class.inc.php";\n\n$e = &$modx->Event;\n\n$PHx = new PHxParser($phxdebug,$phxmaxpass);\n\nswitch($e->name) {\n	case \'OnParseDocument\':\n		$PHx->OnParseDocument();\n		break;\n\n}', 0, '', 0, ' '),
(13, 'TransAlias', '<strong>1.0.4</strong> Human readible URL translation supporting multiple languages and overrides', 0, 3, 0, 'require MODX_BASE_PATH.\'assets/plugins/transalias/plugin.transalias.php\';', 0, '&table_name=Trans table;list;common,russian,dutch,german,czech,utf8,utf8lowercase;russian &char_restrict=Restrict alias to;list;lowercase alphanumeric,alphanumeric,legal characters;lowercase alphanumeric &remove_periods=Remove Periods;list;Yes,No;No &word_separator=Word Separator;list;dash,underscore,none;dash &override_tv=Override TV name;string;', 0, ''),
(14, 'TinyMCE Rich Text Editor', '<strong>3.5.11</strong> Javascript WYSIWYG Editor', 0, 3, 0, 'require MODX_BASE_PATH.\'assets/plugins/tinymce/plugin.tinymce.php\';\n', 0, '&customparams=Custom Parameters;textarea;valid_elements : "*[*]", &mce_formats=Block Formats;text;p,h1,h2,h3,h4,h5,h6,div,blockquote,code,pre &entity_encoding=Entity Encoding;list;named,numeric,raw;named &entities=Entities;text; &mce_path_options=Path Options;list;Site config,Absolute path,Root relative,URL,No convert;Site config &mce_resizing=Advanced Resizing;list;true,false;true &disabledButtons=Disabled Buttons;text; &link_list=Link List;list;enabled,disabled;enabled &webtheme=Web Theme;list;simple,editor,creative,custom;simple &webPlugins=Web Plugins;text;style,advimage,advlink,searchreplace,contextmenu,paste,fullscreen,xhtmlxtras,media &webButtons1=Web Buttons 1;text;undo,redo,selectall,|,pastetext,pasteword,|,search,replace,|,hr,charmap,|,image,link,unlink,anchor,media,|,cleanup,removeformat,|,fullscreen,code,help &webButtons2=Web Buttons 2;text;bold,italic,underline,strikethrough,sub,sup,|,|,blockquote,bullist,numlist,outdent,indent,|,justifyleft,justifycenter,justifyright,justifyfull,|,styleselect,formatselect,|,styleprops &webButtons3=Web Buttons 3;text; &webButtons4=Web Buttons 4;text; &webAlign=Web Toolbar Alignment;list;ltr,rtl;ltr &width=Width;text;100% &height=Height;text;500', 0, ''),
(15, 'CodeMirror', '<strong>1.2b</strong> JavaScript library that can be used to create a relatively pleasant editor interface based on CodeMirror 3.13', 0, 3, 0, '$_CM_BASE = \'assets/plugins/codemirror/\';\r\n\r\n$_CM_URL = $modx->config[\'site_url\'] . $_CM_BASE;\r\n\r\nrequire(MODX_BASE_PATH. $_CM_BASE .\'codemirror.plugin.php\');\r\n\r\n', 0, '&theme=Theme;list;default,ambiance,blackboard,cobalt,eclipse,elegant,erlang-dark,lesser-dark,midnight,monokai,neat,night,rubyblue,solarized,twilight,vibrant-ink,xq-dark,xq-light; &indentUnit=Indent unit;int;4 &tabSize=The width of a tab character;int;4 &lineWrapping=lineWrapping;list;true,false;true &matchBrackets=matchBrackets;list;true,false;true &activeLine=activeLine;list;true,false;false &emmet=emmet;list;true,false;true &search=search;list;true,false;true', 0, ''),
(16, 'ManagerManager', '<strong>0.6.2</strong> Customize the MODX Manager to offer bespoke admin functions for end users.', 0, 3, 0, '// You can put your ManagerManager rules EITHER in a chunk OR in an external file - whichever suits your development style the best\n\n// To use an external file, put your rules in /assets/plugins/managermanager/mm_rules.inc.php \n// (you can rename default.mm_rules.inc.php and use it as an example)\n// The chunk SHOULD have php opening tags at the beginning and end\n\n// If you want to put your rules in a chunk (so you can edit them through the Manager),\n// create the chunk, and enter its name in the configuration tab.\n// The chunk should NOT have php tags at the beginning or end.\n\n// See also user-friendly module for editing ManagerManager configuration file ddMMEditor (http://code.divandesign.biz/modx/ddmmeditor).\n\n// ManagerManager requires jQuery 1.9.1, which is located in /assets/plugins/managermanager/js/ folder.\n\n// You don\'t need to change anything else from here onwards\n//-------------------------------------------------------\n\n// Run the main code\ninclude($modx->config[\'base_path\'].\'assets/plugins/managermanager/mm.inc.php\');', 0, '&remove_deprecated_tv_types_pref=Remove deprecated TV types;list;yes,no;yes &config_chunk=Configuration Chunk;text;mm_rules', 0, '');
